{
  "implementation": "def solve(case):
    if not isinstance(case, dict):
        raise ValueError("case must be a dict")
    attempts = case.get('attempts')
    max_attempts = case.get('max_attempts')
    if attempts is None or not isinstance(attempts, list):
        raise ValueError("missing or invalid 'attempts'")
    if max_attempts is None or not isinstance(max_attempts, int):
        raise ValueError("missing or invalid 'max_attempts'")
    num_attempts = len(attempts)
    if num_attempts == 0:
        decision = "retry"
        next_attempt = 1
        memory_append = None
    else:
        last = attempts[-1]
        if last.get('success') is True:
            decision = "terminate"
            next_attempt = num_attempts
            memory_append = None
        else:
            if num_attempts >= max_attempts:
                decision = "terminate"
                next_attempt = num_attempts
                memory_append = {"reflection": last['reflection'], "signature": last['failure_signature']}
            else:
                last_sig = last['failure_signature']
                prev_signatures = [a.get('failure_signature') for a in attempts[:-1]]
                if last_sig in prev_signatures:
                    decision = "terminate"
                    next_attempt = num_attempts
                    memory_append = {"reflection": last['reflection'], "signature": last['failure_signature']}
                else:
                    decision = "retry"
                    next_attempt = num_attempts + 1
                    memory_append = {"reflection": last['reflection'], "signature": last['failure_signature']}
    return {
        "decision": decision,
        "memory_append": memory_append,
        "next_attempt": next_attempt
    }"
}
